export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-1 stage 1: fix B3+B4, B6, F3 in shelf, then verify all three',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const BASE = args.prompt
const VERDICTS = {
  type: 'object',
  properties: {
    verdicts: { type: 'array', items: { type: 'object', properties: {
      item: { type: 'string' }, passed: { type: 'boolean' }, evidence: { type: 'string' }, why: { type: 'string' },
      parked: { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
        options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
        recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
        genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
        done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
        required: ['question','header','options','default','reason','genuine','gated','files','stop'] },
    }, required: ['item', 'passed', 'evidence'] } },
  },
  required: ['verdicts'],
}
phase('Fix')
const reports = await parallel(args.items.map(it => () =>
  agent(`${BASE}\n\nYOU OWN ONLY item ${it.id} (files: ${it.files}). Other agents are editing the other items' files at the same time - do not touch them. Report what you changed, any Ruling:, and the pytest result line.`,
    { label: `AAAB fix:${it.id}`, phase: 'Fix' })))
phase('Verify')
const v = await agent(`${BASE}\n\nYou are the VERIFIER for this stage. Three fix agents worked in parallel; their reports:\n\n${args.items.map((it, i) => `--- ${it.id} ---\n${reports[i] || '(agent returned nothing)'}`).join('\n\n')}\n\nFor each item (${args.items.map(i => i.id).join(', ')}): read the diff (git diff and new untracked files), check the code meets the ticket, run \`python -m pytest\` yourself and also exercise the behaviour directly (e.g. \`python -c ...\`). passed=true only if a check you ran proves it; evidence must name that check and its output. Do not edit code. If a report says PARKED: check that the independent part works, check (git diff) that the gated files hold no partial guess, judge whether the decision is genuinely the user's, and list every file the gated part would touch; parked.files is the union of yours and the fixer's.`,
  { label: 'AAAB verify:all', phase: 'Verify', schema: VERDICTS })
return { reports, verdicts: v && v.verdicts }

